import { defineCollection } from 'astro:content';
import { glob } from 'astro/loaders';
import { z } from 'astro/zod';

// English collections are GENERATED by importer/import_manuscript.py;
// the *Bg collections by importer/translate.py (src/content/bg/).
// Entries are keyed by file path so English and Bulgarian ids match.
const byPath = ({ entry }: { entry: string }) => entry.replace(/\.md$/, '');

const chapterSchema = z.object({
  number: z.number(),
  label: z.string(),
  title: z.string(),
  manuscriptHeading: z.string(),
  slug: z.string(),
  part: z.number().nullable(),
  partTitle: z.string().nullable(),
  partSlug: z.string().nullable(),
  standfirst: z.string(),
  standfirstHtml: z.string(),
  openingTitle: z.string().nullable(),
  description: z.string(),
  status: z.string(),
  edition: z.number().nullable(),
  sectionCount: z.number(),
  readingTime: z.number(),
  openingReadingTime: z.number(),
});

const sectionSchema = z.object({
  title: z.string(),
  manuscriptTitle: z.string(),
  chapter: z.number(),
  chapterLabel: z.string(),
  chapterSlug: z.string(),
  chapterTitle: z.string(),
  part: z.number().nullable(),
  order: z.number(),
  number: z.number().nullable(),
  type: z.enum(['section', 'summary', 'practice', 'flashcards', 'sources']),
  slug: z.string(),
  readingTime: z.number(),
  description: z.string(),
});

const pageSchema = z.object({
  title: z.string(),
  slug: z.string(),
  description: z.string(),
  readingTime: z.number(),
});

const coll = <S extends z.ZodObject>(base: string, schema: S, pattern = '*.md') =>
  defineCollection({ loader: glob({ pattern, base, generateId: byPath }), schema });

export const collections = {
  chapters: coll('./src/content/chapters', chapterSchema),
  sections: coll('./src/content/sections', sectionSchema, '**/*.md'),
  pages: coll('./src/content/pages', pageSchema),
  chaptersBg: coll('./src/content/bg/chapters', chapterSchema),
  sectionsBg: coll('./src/content/bg/sections', sectionSchema, '**/*.md'),
  pagesBg: coll('./src/content/bg/pages', pageSchema),
};
